"""Render the current static evidence desk deterministically; no network is required."""
from pathlib import Path
import json
from html import escape as e

ROOT = Path(__file__).resolve().parents[1]
DOCS = ROOT / "docs"


def build():
    audit = json.loads((ROOT / "evidence/audit.json").read_text())
    old_audit = json.loads((DOCS / "audit.json").read_text())
    old = {r["repo"]: r for r in old_audit["rows"]}
    focus = {r["site"]: r for r in json.loads((ROOT / "registry/focus_historical.json").read_text())["files"]}
    rows = []
    for r in audit["historical_files"]:
        # Refuse to mix historical byte identities from the two forensic reviews.
        prior = old[r["site"]]
        claim = focus[r["site"]]
        if (prior["sha256"] != r["sha256"] or claim["sha256"] != r["sha256"] or
                claim["owner_claim_not_receipt"] != prior["owner_reported_leaderboard_score"]):
            raise ValueError("Historical audit SHA/claim mismatch for " + r["site"])
        pairs = [x for x in audit["historic_pairwise_comparisons"] if x["candidate"] == r["site"]]
        worst = max(x["directed_overlap_within_3px"] for x in pairs)
        link = f"https://github.com/buffedlizard55-lab/{r['site']}/blob/{r['ref']}/{r['path']}"
        status = "Pass" if prior["local_validation"]["format_pass"] else "Fails all-finite policy"
        rows.append(f'''<tr><td>{e(r['site'])}</td><td><a href="{e(link, quote=True)}">{e(Path(r['path']).name)} ↗</a><small>Hash-pinned historical reference</small></td><td>{claim['owner_claim_not_receipt']:.4f}<small>Unverified owner claim</small></td><td>{r['positive_pixels']:,}</td><td>{worst:.1%}<small>Worst of eight peers</small></td><td>{status}<small>Local check only</small></td><td><span class="no">DO NOT SUBMIT</span></td></tr>''')
    w, l = audit["saturation_witness"], audit["lattice"]
    if not w["universal_overlap_blocker"]:
        raise ValueError("The published stop page requires a verified saturation certificate")
    head = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="A reproducible evidence review of GEMS missing-fault research and submission readiness."><title>GEMS | Evidence &amp; submission review</title><link rel="stylesheet" href="decision.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="topbar"><div class="container navwrap"><a class="brand" href="index.html"><span class="brandmark" aria-hidden="true">✳</span> GEMS <em>RESEARCH DESK</em></a><nav class="nav" aria-label="Main navigation"><a href="index.html#evidence">Evidence</a><a href="index.html#history">Historical review</a><a href="hypotheses.html">Hypotheses</a><a class="nav-cta" href="executive-summary.html">Submission guide ↗</a></nav></div></header>'''
    foot = '''<footer class="footer"><div class="container footer-row"><div><strong>GEMS / RESEARCH DESK</strong><p>Maximize P(Win). Own the Outcome.</p></div><div>Evidence snapshot · 26 October 2026 UTC<br><a href="review.html">Scientific review</a> · <a href="data/current-run-card.json">Current run card</a></div></div></footer></body></html>'''
    page = head + f'''<main id="main"><section class="hero"><div class="container hero-grid"><div><span class="eyebrow">Fault discovery · evidence before promotion</span><h1>Better research starts with an honest&nbsp;stop.</h1><p>We reviewed nine prior GEMS projects and tested whether a new fault prediction could meet the parallel-run uniqueness rule. The result is clear: do not submit a file from this run.</p><div class="actions"><a class="button primary" href="#evidence">Explore the evidence <span aria-hidden="true">↓</span></a><a class="button" href="executive-summary.html">Submission guide <span aria-hidden="true">↗</span></a></div></div><aside class="decision-card" aria-label="Current decision"><span class="overline">Current decision</span><strong>No candidate cleared</strong><span class="status-pill">DO NOT SUBMIT</span><p>No new TIFF was generated or approved. Format validity, geological promise and authorization are separate gates.</p><div class="mini-metrics"><div><b>0</b><span>model experiments</span></div><div><b>0</b><span>TIFFs released</span></div><div><b>0</b><span>slots used</span></div></div></aside></div></section>
<section id="evidence" class="section"><div class="container"><div class="section-head"><div><span class="kicker">01 / The decisive evidence</span><h2>A single witness blocks<br>every nonempty candidate.</h2></div><p>This is a geometric proof under the requested literal rule, not a forecast of model performance.</p></div><div class="proof-grid"><div class="card"><div class="proof-title"><h3>Prior raster coverage</h3><span class="badge">Locally verified</span></div><p>The pinned 17GEMSDOE raster is positive on every valid footprint cell. Under the unchanged template's <code>finite &gt; 0</code> support rule, each nonempty candidate dot overlaps it.</p><div class="bar-label"><span>Candidate overlap with witness</span><span>100%</span></div><div class="bar" role="img" aria-label="Witness overlap is 100 percent; the duplicate threshold is greater than 70 percent."><span class="bar-fill"></span><span class="bar-stop"></span></div><div class="bar-foot"><span>0%</span><span>70% stop threshold</span><span>100%</span></div><p class="proof-note">{w['positive_inside_footprint']:,} footprint cells covered · {w['uncovered_allowed_pixels']:,} uncovered eligible cells · <a href="data/registry-audit.json">Reproduce the proof ↗</a></p></div><div class="card"><div class="proof-title"><h3>What this does—and doesn't—prove</h3></div><ul><li>100% exceeds the &gt;70% duplicate stop; no placement or new TIFF is compliant under the literal protocol.</li><li>One disqualifying raster proves rejection; it is <strong>not</strong> a complete registry scan.</li><li>An independent lattice leaves only {l['uncovered_footprint_pixels']:,} cells outside its 3-pixel radius; more than {l['maximum_dots_to_allow_at_most_70_percent_overlap']:,} dots would necessarily fail it.</li><li>Resolving this conflict requires explicit protocol clarification; we did not silently invent an exemption.</li></ul><a href="review.html">Read the scientific review →</a></div></div></div></section>
<section id="history" class="section alt"><div class="container"><div class="section-head"><div><span class="kicker">02 / Nine-site review</span><h2>The historical picture.</h2></div><p>Files below are historical references, not new downloads to submit. Listed values are unverified owner reports, not organizer-confirmed scores or forecasts.</p></div><div class="table-wrap" role="region" aria-label="Historical comparison table" tabindex="0"><table><thead><tr><th scope="col">Site</th><th scope="col">Reported historical best</th><th scope="col">Owner claim</th><th scope="col">Positive cells</th><th scope="col">3-px overlap</th><th scope="col">Format</th><th scope="col">Submission</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p class="table-note">Overlap is the largest directed fraction within 3 pixels of another of these eight files; all 72 directed comparisons exceed 70%. Format is the older local all-finite check, not portal acceptance; the official wording requires null/NaN outside bounds. Numbers in the table are not HOLDOUT-DTI.</p><div class="lineage"><strong>Why GEMSDOE32 matters.</strong> The 25 and 30 masks are identical; 31 and 32 are successive mapped-fault-collar removals of that family, and 36 contains the 32 mask plus 1,200 dots. Reduced prediction mass is a plausible explanation for a changed result, not a proven cause of the unverified 0.2778 claim. No defensible leaderboard estimate is available.</div></div></section>
<section class="section"><div class="container"><div class="section-head"><div><span class="kicker">03 / Research queue</span><h2>Hypotheses, not promises.</h2></div><p>Qualitative ranking by potential information gain. None has been trained, tested or assigned as the single method lane.</p></div><div class="hyp-grid"><article class="hyp-card"><span class="hyp-num">01 / HIGHEST PRIORITY</span><h3>Radiometric texture displacement</h3><p>Match offset K/Th/U textures across independent magnetic lineaments to look beyond mapped traces.</p></article><article class="hyp-card"><span class="hyp-num">02 / RESEARCH IDEA</span><h3>Magnetic offset coherence</h3><p>Compare opposite-side magnetic patterns over multiple scales, rather than selecting strong edges alone.</p></article><article class="hyp-card"><span class="hyp-num">03 / RESEARCH IDEA</span><h3>Relief termination pairs</h3><p>Look for repeated paired geomorphic terminations across a geophysical line, with coverage uncertainty.</p></article><article class="hyp-card"><span class="hyp-num">04 / RESEARCH IDEA</span><h3>Thermal asymmetry</h3><p>Test sparse shallow-probe contrast after terrain and sampling corrections; not a vent prediction.</p></article></div><p class="table-note"><a href="hypotheses.html">Explore mechanisms, mimics, costs and data availability →</a></p></div></section>
<section class="section alt"><div class="container sources"><div><span class="kicker">04 / Provenance</span><h2>Know what the evidence can say.</h2><p>The core stack, selected derived layers and shared template were restored from pinned owner mirrors. Matching hashes prove mirror integrity, not official origin, data permission, holdout quality or competition acceptance. The official data page required login.</p><p>Our comparison is reproducible; the holdout score, confidence interval, new raster hash and submission name remain null because no experiment or file exists.</p><a href="data/current-run-card.json">Open the current run card →</a></div><div class="card"><h3>Sources for independent review</h3><ul><li><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/">Official task, metric &amp; format</a></li><li><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Official leaderboard</a> · 0.4437 public context observed 26 Oct 2026; not a file-bound receipt, may change</li><li><a href="https://github.com/drivendataorg/gems-prize-reference-solution">Official reference solution</a></li><li><a href="https://www.usgs.gov/data/geodawn-airborne-magnetic-and-radiometric-surveys-northwestern-great-basin-nevada-and">USGS GeoDAWN data release</a></li><li><a href="https://gdr.openei.org/submissions/1391">GDR / INGENIOUS data</a></li><li><a href="audit.json">Earlier nine-file audit</a> · <a href="data/registry-audit.json">Current witness and lineage audit</a></li></ul></div></div></section></main>''' + foot
    (DOCS / "index.html").write_text(page, encoding="utf-8")
    guide = head + '''<main id="main" class="container guide"><div class="guide-intro"><span class="eyebrow">Submission guide</span><h1>From evidence to an eligible file.</h1><p class="muted">A practical checklist for a future authorized run. This page does not upload, select or reserve a competition slot.</p><div class="warning"><h2>Current status: DO NOT SUBMIT</h2><p>No new TIFF exists, no download is authorized for competition use, and no submission name or score estimate is available. The literal uniqueness rule blocks every nonempty candidate.</p></div></div><section class="guide-card"><span class="kicker">Step 01</span><h2>Resolve the stop, without inventing exemptions</h2><p>The method lane is not specified, and a verified positive-everywhere prior causes 100% overlap. A single prior is sufficient to reject but cannot prove registry completeness. Do not continue placement unless the protocol owner explicitly clarifies the applicable policy and lane. Preserve the old audit and regenerate evidence after any authorized change.</p></section><section class="guide-card"><span class="kicker">Step 02</span><h2>Reproduce the evidence and scientific gates</h2><pre><code>python -m venv .venv
.venv/bin/pip install -r requirements.txt
.venv/bin/python scripts/restore_assets.py --focus --features --external
.venv/bin/python scripts/audit_evidence.py</code></pre><p>Run from the repository root with GitHub CLI installed. Restoration downloads public owner mirrors into an ignored cache; hashes establish integrity, not organizer authentication. If access or a hash check fails, stop. Follow official data-use rules separately.</p><ol><li>Hide whole fault segments with a buffer, rebuild every catalogue-based feature from visible faults only, and mask visible faults pixel-exactly.</li><li>Test each feature alone. AUC above 0.90 is a leakage alarm until disproved.</li><li>Use the unchanged shared evaluator: pooled HOLDOUT-DTI with α=.2, β=.8 and a 300 m triangular kernel. Record evaluator version, withheld-positive count, 95% spatial confidence interval, and paired comparison with the same-fold incumbent.</li><li>Check every applicable registry raster both before placement and on the final dots. Stop if rank correlation is &gt;.90 or directed overlap within 3 pixels is &gt;70%; missing registry data is not a pass.</li></ol></section><section class="guide-card"><span class="kicker">Step 03</span><h2>Validate the actual saved GeoTIFF</h2><p>Use the verified shared submission writer; do not rename or perturb an old file. The official task calls for one float32 probability band, values [0,1], EPSG:32611, and the exact 100 m reference grid. The official page specifies null/NaN outside bounds; the shared project's all-finite local policy is a separate assumption about saved pixels, and a local pass is not portal acceptance.</p><pre><code>.venv/bin/python scripts/check_submission.py path/to/candidate.tif --surface path/to/surface.tif --out evidence/preflight.json</code></pre><p>The preflight compares the supplied bytes against the shared local validators and the single witness. It intentionally returns nonzero and <code>ok_to_submit: false</code>; it cannot establish full-registry clearance, holdout quality, official acceptance, or selector approval. It never repairs or uploads a file. A range error must be investigated from the saved bytes, not hidden by clipping.</p></section><section class="guide-card"><span class="kicker">Step 04</span><h2>Only after separate selector approval</h2><p>Confirm current competition rules and rolling weekly cap on the <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/">DrivenData competition page</a>. A separate selector must authorize an eligible, validated exact file. Navigate to the submission page, choose that file, and use the selector-approved concise name and note of at most 140 characters. Save the submitted SHA-256 and organizer receipt. Do not infer a leaderboard score from a holdout; no slot has been spent by this project.</p><p><a href="index.html">← Back to the executive summary</a> · <a href="data/current-run-card.json">Current run card</a></p></section></main>''' + foot
    (DOCS / "executive-summary.html").write_text(guide, encoding="utf-8")
    hypotheses = head + '''<main id="main" class="container guide"><div class="guide-intro"><span class="eyebrow">Research shortlist</span><h1>Four ways to test what is missing.</h1><p class="muted">Ordered by qualitative potential information gain, not a numerical score forecast. These proposals have not been implemented, and an assigned method lane is still missing.</p><div class="warning"><h2>No geological experiment has run</h2><p>A positive-everywhere registry witness prevents any nonempty candidate from passing the current literal uniqueness rule. No policy exemption is implied.</p></div></div><section class="guide-card"><span class="kicker">01 / Highest-priority proposal</span><h2>Radiometric texture displacement</h2><p>Use magnetic RTP/gradient axes as independent candidate lines. Compare paired K, Th and U texture windows on opposite sides for a coherent along-strike displacement; condition on detrended relief and estimate matching uncertainty.</p><p><strong>Why missing faults?</strong> A fault under cover could offset geochemical patterns without a mapped surface trace. <strong>Alternative:</strong> a depositional fan, lithologic contact, airborne seam or unrelated alteration. The proposed paired-offset test differs conceptually from pointwise ratio fusion; novelty across all prior work is not established. Medium cost.</p></section><section class="guide-card"><span class="kicker">02 / Proposal</span><h2>Cross-scale magnetic-pattern offset</h2><p>Compare opposite-side RTP, TMI and gradient patterns at multiple smoothing scales. A consistent lateral offset could indicate concealed faulting; intrusive contacts, remanence or flightline artifacts can mimic it. Unlike a simple gradient maximum, this explicitly matches displaced textures. Medium cost; possible overlap with hypothesis 1.</p></section><section class="guide-card"><span class="kicker">03 / Proposal</span><h2>Relief and lineament termination pairs</h2><p>Seek repeated, coherent paired terminations in detrended elevation, slope and LiDAR scarp features across an independent geophysical axis. Drainage capture, erosion, fans and roads can mimic discontinuities. This proposes paired geometry rather than a standalone scarp score; missing LiDAR coverage must not be imputed as geology. Moderate-to-high cost.</p></section><section class="guide-card"><span class="kicker">04 / Proposal</span><h2>Terrain-adjusted thermal asymmetry</h2><p>Test shallow-probe temperature contrasts across independently proposed lineaments after accounting for terrain, geography and sampling season. Groundwater transport, seasonal effects and land use are alternatives. Sparse biased measurements make expected information lower and cost high; a thermal anomaly is not proof of a vent or resource.</p></section><section class="guide-card"><h2>Data, access and next experiment</h2><p>The <a href="https://www.usgs.gov/data/geodawn-airborne-magnetic-and-radiometric-surveys-northwestern-great-basin-nevada-and">USGS GeoDAWN release</a> lists CC0 data. Hash-verified owner-mirror derivatives and the 19-band feature raster were restored, but raw-file provenance, licenses and coverage are not fully authenticated. A <a href="https://gdr.openei.org/submissions/1391">GDR / INGENIOUS</a> temperature archive was restored from the owner mirror; observation utility remains unverified. The organizer data tab redirected to login.</p><p>Never use the mirrored <code>dist_known_fault_px</code> field as a predictor. After explicit protocol clarification and lane assignment, rebuild catalogue-derived inputs from visible faults within whole-segment buffered folds, test each feature for leakage, and compare matched pooled HOLDOUT-DTI with a spatial 95% CI and paired baseline difference. Stop after three experiments or two hours; only a separate selector may choose a slot.</p><p><a href="hypotheses.md">Full preregistration and source details ↗</a> · <a href="index.html">Back to overview →</a></p></section></main>''' + foot
    (DOCS / "hypotheses.html").write_text(hypotheses, encoding="utf-8")
    review = head + '''<main id="main" class="container guide"><div class="guide-intro"><span class="eyebrow">Scientific review</span><h1>What the evidence actually shows.</h1><p class="muted">A verified geometric blocker, a nine-file historical comparison, and a clear distinction between a valid file and a validated discovery.</p></div><section class="guide-card"><span class="kicker">01 / Decision</span><h2>Why the run stopped</h2><p>A SHA-verified 17GEMSDOE prior is positive at every one of the 5,167,373 valid footprint pixels. The unchanged template treats every finite value &gt;0 as support. Thus, any nonempty prediction supported on the footprint has 100% of dots within zero pixels of this witness, exceeding the required &gt;70% stop. One witness is conclusive for rejection but is not a complete registry scan.</p><p>The independent spacing-5 lattice covers 5,160,724 footprint cells within 3 pixels; only 6,649 lie outside. More than 22,163 distinct dots necessarily violate the same 70% threshold against the lattice. <a href="data/registry-audit.json">Inspect the machine-readable certificate ↗</a></p></section><section class="guide-card"><span class="kicker">02 / Historical evidence</span><h2>Related masks, not independent wins</h2><p>All 72 directed comparisons among the nine reviewed historical masks exceed the threshold. GEMSDOE25 and 30 share a decoded footprint mask. GEMSDOE31 and 32 are successive 1- and 2-pixel catalogue-collar removals; 36 contains all 37,654 GEMSDOE32 dots plus 1,200. These facts describe geometry, not a cause of performance.</p><p>The 0.2778 GEMSDOE32 value is an unverified owner report. No file-bound submission receipt was identified, and lack of one does not prove no submission was scored. The public leaderboard showed 0.4437 on 26 October 2026. This is context, not an accepted file-bound result under the project receipt rule, and it may change.</p></section><section class="guide-card"><span class="kicker">03 / Trust boundaries</span><h2>Four different evidence classes</h2><ul><li><strong>REGISTRY-MEASUREMENT:</strong> reproducible geometry and support; not model performance.</li><li><strong>HOLDOUT-DTI:</strong> pooled spatial evaluation with evaluator version, withheld positives and 95% confidence interval; not run here.</li><li><strong>ORGANIZER-CONFIRMED:</strong> a submission-page receipt tied to the exact file; none identified here.</li><li><strong>Owner report or projection:</strong> an unverified lead, not an established score.</li></ul><p>Public owner-mirror hashes establish integrity, not official origin, licensing, absence of leakage or permission to train. The sample's positive cells reproduce the catalogue, so use it only for its grid and footprint, never as a predictor. A <a href="SHARED_TEMPLATE_ISSUE.md">shared metric docstring claim</a> was disproved by a synthetic example; the exact evaluator was not shown defective, and upstream issue creation was denied by the integration.</p></section><section class="guide-card"><span class="kicker">04 / Reproducible continuation</span><h2>What would be needed next</h2><p>Clarify the conflicting protocol and missing lane; verify authorized data and the complete applicable registry; construct whole-segment buffered folds; rebuild catalogue features from visible faults only; run canaries, a matched pooled DTI comparison and paired 95% CI; then validate the exact output with unchanged shared tools. Scientific eligibility and weekly-slot selection are separate. No slot was used.</p><p><a href="review.md">Full scientific review ↗</a> · <a href="index.html">Back to overview →</a></p></section></main>''' + foot
    (DOCS / "review.html").write_text(review, encoding="utf-8")
    (DOCS / "data").mkdir(exist_ok=True)
    (DOCS / "data/registry-audit.json").write_text((ROOT / "evidence/audit.json").read_text(), encoding="utf-8")
    (DOCS / "data/current-run-card.json").write_text((ROOT / "evidence/run-card.json").read_text(), encoding="utf-8")
    for src in ["review", "hypotheses"]:
        (DOCS / f"{src}.md").write_text((ROOT / f"research/{src}.md").read_text(), encoding="utf-8")


if __name__ == "__main__":
    build()
